function* main() {
  var result = yield Promise.resolve(21);
  var doubled = yield Promise.resolve(result * 2);
  return doubled;
}
function run(gen) {
  var it = gen();
  function step(val) {
    var res = it.next(val);
    if (res.done) {
      console.log('final:', res.value);
      return;
    }
    res.value.then(step);
  }
  step();
}
run(main);

